SELECT jsonb_build_object('functions',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'definition',pg_get_functiondef(p.oid))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN('ai_profile_get','ai_profile_save')),'columns',(SELECT jsonb_agg(jsonb_build_object('name',column_name,'type',data_type)) FROM information_schema.columns WHERE table_schema='zoi' AND table_name='ai_profiles')) AS ai_contract_review;
